param(
  [string]$ProjectRoot = "D:\simras-digital-twin-repository\simras-digital-twin"
)

$ErrorActionPreference = "Stop"
Set-Location $ProjectRoot
[Environment]::CurrentDirectory = (Get-Location).Path

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $ProjectRoot "archive\twin_source_reset_$stamp"
New-Item -ItemType Directory -Force $backup | Out-Null

$files = @(
  ".\frontend\src\features\digital-twin\TwinPanels.tsx",
  ".\frontend\src\features\digital-twin\EvidenceStatePanel.tsx"
)

foreach ($file in $files) {
  if (Test-Path $file) {
    Copy-Item $file (Join-Path $backup (Split-Path $file -Leaf)) -Force
  }
}

Write-Host "`n=== 1. RESTORE KNOWN-GOOD TWIN PANELS ===" -ForegroundColor Cyan

[IO.File]::WriteAllBytes(
  ".\frontend\src\features\digital-twin\TwinPanels.tsx",
  [Convert]::FromBase64String("")
)

[IO.File]::WriteAllBytes(
  ".\frontend\src\features\digital-twin\EvidenceStatePanel.tsx",
  [Convert]::FromBase64String("")
)

Write-Host "TwinPanels.tsx restored" -ForegroundColor Green
Write-Host "EvidenceStatePanel.tsx restored" -ForegroundColor Green

Write-Host "`n=== 2. TARGETED GLOBAL CORRUPTION REPAIR ===" -ForegroundColor Cyan

@'
from pathlib import Path
import re

src = Path("frontend/src")
changed = []

# Only expressions we have actually observed being corrupted during this merge.
replacements = [
    (r'Number\(([^()\n]+?)\s\?\s0\)', r'Number(\1 ?? 0)'),
    (r'String\(([^()\n]+?)\s\?\s""\)', r'String(\1 ?? "")'),
    (r'\b(record\.[A-Za-z_]\w*)\s\?\s(record\.[A-Za-z_]\w*)', r'\1 ?? \2'),
    (r'\b(inspection\.[A-Za-z_]\w*)\s\?\s(inspection\.[A-Za-z_]\w*)', r'\1 ?? \2'),
    (r'\b(asset\.[A-Za-z_]\w*)\s\?\s(asset\.[A-Za-z_]\w*)', r'\1 ?? \2'),
    (r'\b(item\.[A-Za-z_]\w*)\s\?\s(item\.[A-Za-z_]\w*)', r'\1 ?? \2'),
]

for p in src.rglob("*"):
    if not p.is_file() or p.suffix not in {".ts", ".tsx"}:
        continue

    text = p.read_text(encoding="utf-8-sig")
    original = text

    for pattern, replacement in replacements:
        text = re.sub(pattern, replacement, text)

    if text != original:
        p.write_text(text, encoding="utf-8")
        changed.append(str(p))

print("Targeted files repaired:", len(changed))
for item in changed:
    print(" ", item)
'@ | py -

Write-Host "`n=== 3. FULL TYPESCRIPT/VITE BUILD ===" -ForegroundColor Cyan

Push-Location ".\frontend"

if (Test-Path ".\node_modules\.vite") {
  Remove-Item ".\node_modules\.vite" -Recurse -Force -ErrorAction SilentlyContinue
}

npm run build
$buildExit = $LASTEXITCODE

Pop-Location

if ($buildExit -ne 0) {
  Write-Host "`nBUILD STILL HAS A DIFFERENT SOURCE ERROR." -ForegroundColor Red
  Write-Host "Running container was NOT replaced." -ForegroundColor Yellow
  Write-Host "Backup: $backup"
  throw "SEND ONLY THE FIRST NEW FILE:LINE ERROR"
}

Write-Host "`nFRONTEND BUILD PASS" -ForegroundColor Green

Write-Host "`n=== 4. BACKEND HEALTH ===" -ForegroundColor Cyan

py -m py_compile ".\backend\app\main.py"
if ($LASTEXITCODE -ne 0) {
  throw "BACKEND COMPILE FAILED"
}

docker compose ps

Write-Host "`n=== 5. REBUILD FRESH FRONTEND CONTAINER ===" -ForegroundColor Cyan

docker compose build frontend
if ($LASTEXITCODE -ne 0) {
  throw "FRONTEND DOCKER IMAGE BUILD FAILED"
}

docker compose stop frontend
docker compose rm -f frontend
docker compose up -d --force-recreate --renew-anon-volumes frontend

Start-Sleep -Seconds 7

Write-Host "`n=== 6. VERIFY EXACT SOURCE INSIDE CONTAINER ===" -ForegroundColor Cyan

docker compose exec -T frontend sh -lc "sed -n '25,45p' /app/src/features/digital-twin/TwinPanels.tsx"
docker compose exec -T frontend sh -lc "sed -n '35,60p' /app/src/features/digital-twin/EvidenceStatePanel.tsx"

Write-Host "`n=== 7. LIVE CONNECTION CHECK ===" -ForegroundColor Cyan

function Test-Url {
  param([string]$Name,[string]$Url)
  $code = curl.exe -s -o NUL -w "%{http_code}" $Url
  if ($code -eq "200") {
    Write-Host ("{0,-22} PASS ({1})" -f $Name,$code) -ForegroundColor Green
  } else {
    Write-Host ("{0,-22} CHECK ({1})" -f $Name,$code) -ForegroundColor Yellow
  }
}

Test-Url "Frontend" "http://localhost:5173/"
Test-Url "Digital Twin" "http://localhost:5173/digital-twin"
Test-Url "Backend docs" "http://localhost:8000/docs"
Test-Url "Assets API" "http://localhost:8000/api/v1/assets?limit=3"
Test-Url "Twin API" "http://localhost:8000/api/v1/assets/AP_DAM_00001/twin"
Test-Url "Model status" "http://localhost:8000/api/v1/analytics/models/status"

Write-Host "`n============================================================" -ForegroundColor Green
Write-Host "TWIN SOURCE RESET + BUILD COMPLETE" -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host "Backup: $backup"

Start-Process "http://localhost:5173/digital-twin"
